using System.Security.Cryptography;
using System.Net;
using System.Text;
using System.Text.Json;
using FluentValidation;
using UrlShortener.Application.Repositories;
using UrlShortener.Domain;

namespace UrlShortener.Application.Links;

public sealed class LinkService(IValidator<CreateLinkRequest> validator, ILinkCreationRepository creation,
    IShortLinkRepository links, IRedirectStore redirects, ILinkStatsRepository stats,
    ICodeGenerator generator, TimeProvider clock)
{
    public async Task<ShortLink> CreateAsync(CreateLinkRequest request, string? key,
        IReadOnlyCollection<string> ownHosts, CancellationToken ct = default)
    {
        await validator.ValidateAndThrowAsync(request, ct);
        if (key is not null && (string.IsNullOrWhiteSpace(key) || key.Length > 128 || key.Any(char.IsControl)))
            throw new LinkOperationException(400, "Idempotency-Key must contain 1–128 non-control characters.");
        var target = new Uri(request.LongUrl);
        if (ownHosts.Any(host => string.Equals(host.TrimEnd('.'), target.IdnHost.TrimEnd('.'), StringComparison.OrdinalIgnoreCase)
            || (IsLoopbackHost(host) && target.IsLoopback)))
            throw new LinkOperationException(400, "The target URL cannot point to this service.");

        var hash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(request))));
        if (key is not null && await creation.FindByKeyAsync(key, ct) is { } previous)
        {
            if (previous.RequestHash != hash) throw new LinkOperationException(409, "Idempotency-Key was used with a different request.");
            return previous.Link;
        }

        var now = clock.GetUtcNow().UtcDateTime;
        if (request.ExpiresAt <= now) throw new LinkOperationException(400, "Expiry must be in the future.");
        var normalizedLongUrl = NormalizeDestination(request.LongUrl);

        // An initial attempt plus at most three collision retries.
        for (var attempt = 0; attempt <= 3; attempt++)
        {
            var code = request.CustomAlias ?? generator.Generate();
            if (request.CustomAlias is null && new[] { "api", "health", "swagger" }.Contains(code, StringComparer.OrdinalIgnoreCase)) continue;
            var result = await creation.TryCreateAsync(new ShortLink(code, normalizedLongUrl, now, request.ExpiresAt), key, hash, ct);
            if (result.Status is CreationStatus.Created or CreationStatus.Replayed) return result.Link!;
            if (result.Status == CreationStatus.KeyConflict) throw new LinkOperationException(409, "Idempotency-Key was used with a different request.");
            if (request.CustomAlias is not null) throw new LinkOperationException(409, "The custom alias is already taken.");
        }
        throw new LinkOperationException(503, "Unable to allocate a unique code. Please retry.");
    }

    private static string NormalizeDestination(string destination)
    {
        var schemeEnd = destination.IndexOf(':');
        var authorityStart = schemeEnd + 3;
        var authorityEnd = destination.IndexOfAny(['/', '?', '#'], authorityStart);
        if (authorityEnd < 0) authorityEnd = destination.Length;

        var authority = destination[authorityStart..authorityEnd];
        var userInfoEnd = authority.LastIndexOf('@');
        var hostStart = userInfoEnd + 1;
        var hostEnd = authority.Length;
        var portStart = -1;

        if (hostStart < authority.Length && authority[hostStart] == '[')
        {
            var closingBracket = authority.IndexOf(']', hostStart);
            if (closingBracket >= 0)
            {
                hostEnd = closingBracket + 1;
                if (hostEnd < authority.Length && authority[hostEnd] == ':') portStart = hostEnd;
            }
        }
        else
        {
            var colon = authority.LastIndexOf(':');
            if (colon >= hostStart)
            {
                hostEnd = colon;
                portStart = colon;
            }
        }

        var host = authority[hostStart..hostEnd].ToLowerInvariant();
        var port = portStart < 0 ? string.Empty : authority[portStart..];
        var scheme = destination[..schemeEnd].ToLowerInvariant();
        if (portStart >= 0 && int.TryParse(port.AsSpan(1), System.Globalization.NumberStyles.None,
                System.Globalization.CultureInfo.InvariantCulture, out var portNumber)
            && ((scheme == Uri.UriSchemeHttp && portNumber == 80)
                || (scheme == Uri.UriSchemeHttps && portNumber == 443)))
        {
            port = string.Empty;
        }

        var normalizedAuthority = authority[..hostStart] + host + port;
        var suffix = destination[authorityEnd..];
        var fragmentIndex = suffix.IndexOf('#');
        var queryIndex = suffix.IndexOf('?');
        if (queryIndex >= 0 && (fragmentIndex < 0 || queryIndex < fragmentIndex))
        {
            var queryEnd = fragmentIndex < 0 ? suffix.Length : fragmentIndex;
            var query = suffix[(queryIndex + 1)..queryEnd];
            var parameters = query.Split('&', StringSplitOptions.None)
                .Where(parameter =>
                {
                    var equalsIndex = parameter.IndexOf('=');
                    var name = equalsIndex < 0 ? parameter : parameter[..equalsIndex];
                    return !name.StartsWith("utm_", StringComparison.OrdinalIgnoreCase);
                })
                .ToArray();

            suffix = parameters.Length == 0
                ? suffix[..queryIndex] + suffix[queryEnd..]
                : suffix[..(queryIndex + 1)] + string.Join('&', parameters) + suffix[queryEnd..];
        }

        return scheme + "://" + normalizedAuthority + suffix;
    }

    private static bool IsLoopbackHost(string host) => host.TrimEnd('.').Equals("localhost", StringComparison.OrdinalIgnoreCase)
        || (IPAddress.TryParse(host.Trim('[', ']'), out var address) && IPAddress.IsLoopback(address));

    public async Task<ShortLink> GetAsync(string code, CancellationToken ct = default) =>
        await links.FindByCodeAsync(code, ct) ?? throw new LinkOperationException(404, "Link not found.");

    public async Task<ShortLink> ResolveAsync(string code, CancellationToken ct = default)
    {
        var link = await redirects.FindAsync(code, ct) ?? throw new LinkOperationException(404, "Link not found.");
        if (!link.IsAvailableAt(clock.GetUtcNow().UtcDateTime)) throw new LinkOperationException(410, "Link has expired or is disabled.");
        return link;
    }

    public async Task DisableAsync(string code, CancellationToken ct = default)
    {
        if (!await redirects.DisableAsync(code, ct)) throw new LinkOperationException(404, "Link not found.");
    }

    public async Task<LinkStats> GetStatsAsync(string code, CancellationToken ct = default)
    {
        var link = await GetAsync(code, ct);
        return await stats.GetAsync(link.Id, ct);
    }
}

using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.OpenApi.Models;
using UrlShortener.Application.Links;
using UrlShortener.Domain;

namespace UrlShortener.Api;

public static class LinkEndpoints
{
    public static void MapLinkEndpoints(this WebApplication app)
    {
        var links = app.MapGroup("/api/v1/links").WithTags("Links");
        links.MapPost("", async (CreateLinkRequest request, LinkService service, HttpContext context,
            IConfiguration configuration, [FromHeader(Name = "Idempotency-Key")] string? key, CancellationToken ct) =>
        {
            if (context.Request.Headers["Idempotency-Key"].Count > 1)
                throw new LinkOperationException(400, "Supply one Idempotency-Key value.");
            var baseUrl = BaseUrl(context, configuration);
            var hosts = new[] { context.Request.Host.Host, new Uri(baseUrl).IdnHost };
            var link = await service.CreateAsync(request, key, hosts, ct);
            return Results.Created($"/api/v1/links/{link.Code}", Response(link, baseUrl));
        }).RequireRateLimiting("create").WithName("CreateLink")
            .WithSummary("Create a short link")
            .WithDescription("Creates a short link to an absolute http(s) URL of at most 2,048 characters (javascript:, data: and this service's own host are rejected). "
                + "The saved destination has its scheme and host lowercased, default ports removed, and utm_ tracking parameters stripped. "
                + "customAlias is optional: 3-30 characters from A-Z, a-z, 0-9, '_' and '-', and not 'api', 'health' or 'swagger'; without it a random 7-character Base62 code is generated. "
                + "expiresAt is optional and must be a future UTC timestamp ending in 'Z'. Creation is rate limited per client IP.")
            .WithOpenApi(operation =>
            {
                var header = operation.Parameters.FirstOrDefault(p => p.Name == "Idempotency-Key");
                if (header is not null)
                    header.Description = "Optional, at most 128 characters. Retrying with the same key and body returns the original link; the same key with a different body returns 409.";
                return operation;
            })
            .Produces<LinkResponse>(201).ProducesValidationProblem().ProducesProblem(409).ProducesProblem(429).ProducesProblem(503);

        links.MapGet("/{code}", async (string code, LinkService service, HttpContext context, IConfiguration configuration, CancellationToken ct) =>
        {
            var link = await service.GetAsync(code, ct);
            return Results.Ok(new LinkDetails(link.Code, $"{BaseUrl(context, configuration)}/{link.Code}", link.LongUrl,
                link.CreatedAtUtc, link.ExpiresAtUtc, link.IsActive, link.ClickCount));
        }).WithName("GetLink").WithSummary("Get link details")
            .WithDescription("Returns the target URL, creation and expiry times (UTC), whether the link is active, and its recorded click count.")
            .WithOpenApi().Produces<LinkDetails>().ProducesProblem(404);

        links.MapGet("/{code}/stats", async (string code, LinkService service, CancellationToken ct) =>
            Results.Ok(await service.GetStatsAsync(code, ct)))
            .WithName("GetLinkStats").WithSummary("Get click statistics")
            .WithDescription("Total clicks, clicks per UTC day and the top 10 referrers. Clicks are recorded in the background, so totals can lag a redirect briefly.")
            .WithOpenApi().Produces<LinkStats>().ProducesProblem(404);

        links.MapDelete("/{code}", async (string code, LinkService service, CancellationToken ct) =>
        {
            await service.DisableAsync(code, ct);
            return Results.NoContent();
        }).WithName("DisableLink").WithSummary("Disable a link")
            .WithDescription("Soft delete: the link and its analytics are kept, and redirects return 410 from now on.")
            .WithOpenApi().Produces(204).ProducesProblem(404);

        app.MapGet("/{code}", async (string code, LinkService service, ClickQueue queue, TimeProvider clock, HttpContext context, CancellationToken ct) =>
        {
            var link = await service.ResolveAsync(code, ct);
            var address = context.Connection.RemoteIpAddress;
            var hash = address is null ? null : Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(address.ToString())));
            var click = new ClickEvent(link.Id, clock.GetUtcNow().UtcDateTime, hash,
                context.Request.Headers.Referer.ToString(), context.Request.Headers.UserAgent.ToString());
            if (!queue.TryWrite(click)) throw new LinkOperationException(503, "Click recording is busy. Please retry.");
            // Prevent browser caching from bypassing subsequent expiry/disable checks and analytics.
            context.Response.Headers.CacheControl = "no-store";
            return Results.Redirect(link.LongUrl);
        }).WithTags("Redirect").WithName("RedirectLink").WithSummary("Follow a short link")
            .WithDescription("Redirects with 302 to the target URL and records the click in the background (the client IP is stored only as a SHA-256 hash). "
                + "Returns 404 for an unknown code and 410 when the link has expired or been disabled. "
                + "Swagger's 'Try it out' cannot show this redirect, because the browser follows it to another origin; open the short URL directly instead.")
            .WithOpenApi(operation =>
            {
                if (!operation.Responses.TryGetValue("302", out var found)) operation.Responses["302"] = found = new OpenApiResponse();
                found.Description = "Found: the client is redirected to the target URL.";
                found.Headers["Location"] = new OpenApiHeader
                {
                    Description = "The link's target URL.",
                    Schema = new OpenApiSchema { Type = "string", Format = "uri" }
                };
                return operation;
            }).Produces(302).ProducesProblem(404).ProducesProblem(410).ProducesProblem(503);
    }

    private static string BaseUrl(HttpContext context, IConfiguration configuration) =>
        (configuration["PublicBaseUrl"] ?? $"{context.Request.Scheme}://{context.Request.Host}{context.Request.PathBase}").TrimEnd('/');

    private static LinkResponse Response(ShortLink link, string baseUrl) =>
        new(link.Code, $"{baseUrl}/{link.Code}", link.LongUrl, link.CreatedAtUtc, link.ExpiresAtUtc);
}

using FluentValidation;
using UrlShortener.Application.Links;
using UrlShortener.Application.Repositories;
using UrlShortener.Domain;
using Xunit;

namespace UrlShortener.UnitTests;

public sealed class LinkServiceTests
{
    private sealed class Clock : TimeProvider
    {
        public override DateTimeOffset GetUtcNow() => new(2026, 10, 17, 12, 0, 0, TimeSpan.Zero);
    }

    private sealed class Generator(params string[] codes) : ICodeGenerator
    {
        public int Calls { get; private set; }
        public string Generate() => codes[Math.Min(Calls++, codes.Length - 1)];
    }

    private sealed class Store : ILinkCreationRepository, IShortLinkRepository, IRedirectStore, ILinkStatsRepository
    {
        public int Failures { get; init; }
        public int Calls { get; private set; }
        public Task<IdempotentLink?> FindByKeyAsync(string key, CancellationToken ct) => Task.FromResult<IdempotentLink?>(null);
        public Task<CreationResult> TryCreateAsync(ShortLink link, string? key, string requestHash, CancellationToken ct)
        {
            ct.ThrowIfCancellationRequested();
            Calls++;
            return Task.FromResult(Calls <= Failures ? new CreationResult(CreationStatus.CodeConflict) : new CreationResult(CreationStatus.Created, link));
        }
        public Task<ShortLink?> FindByCodeAsync(string code, CancellationToken ct = default) => Task.FromResult<ShortLink?>(null);
        public Task<ShortLink?> FindAsync(string code, CancellationToken ct) => Task.FromResult<ShortLink?>(null);
        public Task<bool> TryAddAsync(ShortLink link, CancellationToken ct = default) => throw new NotSupportedException();
        public Task<bool> DisableAsync(string code, CancellationToken ct = default) => Task.FromResult(false);
        public Task<LinkStats> GetAsync(long linkId, CancellationToken ct) => throw new NotSupportedException();
    }

    private static LinkService Service(Store store, Generator generator) =>
        new(new CreateLinkValidator(), store, store, store, store, generator, new Clock());

    [Fact]
    public async Task RetriesCollisionsAtMostThreeTimes()
    {
        var store = new Store { Failures = int.MaxValue };
        var generator = new Generator("Abc1234");
        var exception = await Assert.ThrowsAsync<LinkOperationException>(() =>
            Service(store, generator).CreateAsync(new("https://example.com"), null, ["localhost"]));
        Assert.Equal(503, exception.StatusCode);
        Assert.Equal(4, store.Calls);
        Assert.Equal(4, generator.Calls);
    }

    [Fact]
    public async Task ThirdRetryCanSucceed()
    {
        var store = new Store { Failures = 3 };
        var generator = new Generator("Abc1234", "Bbc1234", "Cbc1234", "Dbc1234");
        var result = await Service(store, generator).CreateAsync(new("https://example.com"), null, ["localhost"]);
        Assert.Equal("Dbc1234", result.Code);
        Assert.Equal(4, store.Calls);
    }

    [Fact]
    public async Task CustomAliasConflictIsNotRetried()
    {
        var store = new Store { Failures = 100 };
        var generator = new Generator("Abc1234");
        var exception = await Assert.ThrowsAsync<LinkOperationException>(() =>
            Service(store, generator).CreateAsync(new("https://example.com", "custom"), null, ["localhost"]));
        Assert.Equal(409, exception.StatusCode);
        Assert.Equal(1, store.Calls);
        Assert.Equal(0, generator.Calls);
    }

    [Fact]
    public async Task GeneratedReservedCodeIsSkipped()
    {
        var store = new Store();
        var generator = new Generator("swagger", "Abc1234");
        var link = await Service(store, generator).CreateAsync(new("https://example.com"), null, ["localhost"]);
        Assert.Equal("Abc1234", link.Code);
        Assert.Equal(1, store.Calls);
    }

    [Theory]
    [InlineData("HTTP://ExAmPlE.Com:80/path?utm_source=campaign&Keep=Yes#section", "http://example.com/path?Keep=Yes#section")]
    [InlineData("hTtPs://EXAMPLE.COM:443/path?keep=1#part", "https://example.com/path?keep=1#part")]
    [InlineData("HTTP://EXAMPLE.COM:8080/path?UTM_medium=email&x=1&utm_campaign=summer&y=2#fragment", "http://example.com:8080/path?x=1&y=2#fragment")]
    [InlineData("https://EXAMPLE.COM/path?utm_source=one&UtM_Term=two#fragment", "https://example.com/path#fragment")]
    [InlineData("https://EXAMPLE.COM/path?first=one&second=two#fragment", "https://example.com/path?first=one&second=two#fragment")]
    public async Task NormalizesDestinationWhilePreservingOtherUrlParts(string input, string expected)
    {
        var store = new Store();
        var link = await Service(store, new("Abc1234")).CreateAsync(new(input), null, ["localhost"]);
        Assert.Equal(expected, link.LongUrl);
    }

    [Theory]
    [InlineData("")]
    [InlineData(" ")]
    [InlineData("bad\nkey")]
    public async Task InvalidIdempotencyKeyDoesNotWrite(string key)
    {
        var store = new Store();
        var exception = await Assert.ThrowsAsync<LinkOperationException>(() =>
            Service(store, new("Abc1234")).CreateAsync(new("https://example.com"), key, ["localhost"]));
        Assert.Equal(400, exception.StatusCode);
        Assert.Equal(0, store.Calls);
    }

    [Fact]
    public async Task OverlongIdempotencyKeyDoesNotWrite()
    {
        var store = new Store();
        var exception = await Assert.ThrowsAsync<LinkOperationException>(() =>
            Service(store, new("Abc1234")).CreateAsync(new("https://example.com"), new string('a', 129), ["localhost"]));
        Assert.Equal(400, exception.StatusCode);
        Assert.Equal(0, store.Calls);
    }

    [Theory]
    [InlineData("https://sho.rt/path")]
    [InlineData("http://SHO.RT.:8080/path")]
    public async Task ConfiguredOwnHostIsRejected(string url)
    {
        var store = new Store();
        var exception = await Assert.ThrowsAsync<LinkOperationException>(() =>
            Service(store, new("Abc1234")).CreateAsync(new(url), null, ["localhost", "sho.rt"]));
        Assert.Equal(400, exception.StatusCode);
        Assert.Equal(0, store.Calls);
    }

    [Fact]
    public async Task PastExpiryDoesNotWrite()
    {
        var store = new Store();
        var exception = await Assert.ThrowsAsync<LinkOperationException>(() =>
            Service(store, new("Abc1234")).CreateAsync(new("https://example.com", ExpiresAt: new Clock().GetUtcNow().UtcDateTime), null, ["localhost"]));
        Assert.Equal(400, exception.StatusCode);
        Assert.Equal(0, store.Calls);
    }

    [Fact]
    public async Task MissingUrlProducesValidationFailure()
    {
        var store = new Store();
        await Assert.ThrowsAsync<ValidationException>(() => Service(store, new("Abc1234")).CreateAsync(new(null!), null, ["localhost"]));
        Assert.Equal(0, store.Calls);
    }
}

using System.Diagnostics;
using System.Net;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using UrlShortener.Application.Links;
using UrlShortener.Infrastructure;
using Xunit;

namespace UrlShortener.IntegrationTests;

public sealed class ApiTests(ApiFactory factory) : IClassFixture<ApiFactory>
{
    private async Task<LinkResponse> CreateAsync(HttpClient client, string? alias = null, DateTime? expiry = null)
    {
        using var response = await client.PostAsJsonAsync("/api/v1/links", new CreateLinkRequest("https://example.com/docs", alias, expiry));
        Assert.Equal(HttpStatusCode.Created, response.StatusCode);
        var link = (await response.Content.ReadFromJsonAsync<LinkResponse>())!;
        Assert.Equal($"/api/v1/links/{link.Code}", response.Headers.Location!.OriginalString);
        return link;
    }

    private static async Task AssertProblemAsync(HttpResponseMessage response, HttpStatusCode status)
    {
        Assert.Equal(status, response.StatusCode);
        Assert.Equal("application/problem+json", response.Content.Headers.ContentType!.MediaType);
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal((int)status, body.GetProperty("status").GetInt32());
    }

    [Fact]
    public async Task CreateDetailsAndRedirect()
    {
        using var client = factory.Client();
        var link = await CreateAsync(client);
        Assert.Equal(7, link.Code.Length);
        Assert.Equal($"http://localhost/{link.Code}", link.ShortUrl);
        var details = await client.GetFromJsonAsync<LinkDetails>($"/api/v1/links/{link.Code}");
        Assert.Equal(link.LongUrl, details!.LongUrl);
        Assert.True(details.IsActive);
        using var redirect = await client.GetAsync($"/{link.Code}");
        Assert.Equal(HttpStatusCode.Found, redirect.StatusCode);
        Assert.Equal(link.LongUrl, redirect.Headers.Location!.AbsoluteUri);
        Assert.True(redirect.Headers.CacheControl!.NoStore);
    }

    [Fact]
    public async Task CreateReturnsAndRedirectsToNormalizedDestination()
    {
        using var client = factory.Client();
        var alias = "normalized-" + Guid.NewGuid().ToString("N")[..12];
        const string expected = "https://example.com/docs?keep=1#part";
        using var response = await client.PostAsJsonAsync("/api/v1/links",
            new CreateLinkRequest("HTTPS://ExAmPlE.CoM:443/docs?utm_source=campaign&keep=1&UTM_medium=email#part", alias));
        Assert.Equal(HttpStatusCode.Created, response.StatusCode);
        var link = (await response.Content.ReadFromJsonAsync<LinkResponse>())!;
        Assert.Equal(expected, link.LongUrl);

        var details = await client.GetFromJsonAsync<LinkDetails>($"/api/v1/links/{link.Code}");
        Assert.Equal(expected, details!.LongUrl);
        using var redirect = await client.GetAsync($"/{link.Code}");
        Assert.Equal(HttpStatusCode.Found, redirect.StatusCode);
        Assert.Equal(expected, redirect.Headers.Location!.OriginalString);
    }

    [Fact]
    public async Task DuplicateAliasReturnsConflict()
    {
        using var client = factory.Client();
        var alias = "alias-" + Guid.NewGuid().ToString("N")[..12];
        await CreateAsync(client, alias);
        using var duplicate = await client.PostAsJsonAsync("/api/v1/links", new CreateLinkRequest("https://example.com", alias));
        await AssertProblemAsync(duplicate, HttpStatusCode.Conflict);
    }

    [Theory]
    [InlineData("javascript:alert(1)")]
    [InlineData("data:text/plain,test")]
    [InlineData("http://localhost/self")]
    [InlineData("http://LOCALHOST./self")]
    [InlineData("/relative")]
    [InlineData("http://127.0.0.1/self")]
    [InlineData("http://[::1]/self")]
    [InlineData("https://example.com/\r\nInjected: header")]
    public async Task InvalidUrlsReturnBadRequest(string url)
    {
        using var client = factory.Client();
        using var response = await client.PostAsJsonAsync("/api/v1/links", new CreateLinkRequest(url));
        await AssertProblemAsync(response, HttpStatusCode.BadRequest);
    }

    [Fact]
    public async Task LongUrlAndMalformedJsonReturnBadRequest()
    {
        using var client = factory.Client();
        using var tooLong = await client.PostAsJsonAsync("/api/v1/links", new CreateLinkRequest("https://example.com/" + new string('x', 2048)));
        await AssertProblemAsync(tooLong, HttpStatusCode.BadRequest);
        using var malformed = await client.PostAsync("/api/v1/links", new StringContent("{ broken", Encoding.UTF8, "application/json"));
        await AssertProblemAsync(malformed, HttpStatusCode.BadRequest);
    }

    [Theory]
    [InlineData("api")]
    [InlineData("HEALTH")]
    [InlineData("swagger")]
    [InlineData("ab")]
    [InlineData("bad alias")]
    [InlineData("abc\n")]
    public async Task InvalidAliasesReturnBadRequest(string alias)
    {
        using var client = factory.Client();
        using var response = await client.PostAsJsonAsync("/api/v1/links", new CreateLinkRequest("https://example.com", alias));
        await AssertProblemAsync(response, HttpStatusCode.BadRequest);
    }

    [Fact]
    public async Task UnknownRoutesReturnProblemDetails()
    {
        using var client = factory.Client();
        foreach (var path in new[] { "/not-found", "/api/v1/links/not-found", "/api/v1/links/not-found/stats", "/api/unknown/path" })
        {
            using var response = await client.GetAsync(path);
            await AssertProblemAsync(response, HttpStatusCode.NotFound);
        }
        using var deleted = await client.DeleteAsync("/api/v1/links/not-found");
        await AssertProblemAsync(deleted, HttpStatusCode.NotFound);
    }

    [Fact]
    public async Task CachedLinkExpiresAtBoundary()
    {
        using var client = factory.Client();
        var link = await CreateAsync(client, expiry: factory.Clock.GetUtcNow().UtcDateTime.AddMinutes(1));
        using var first = await client.GetAsync($"/{link.Code}");
        Assert.Equal(HttpStatusCode.Found, first.StatusCode);
        factory.Clock.Advance(TimeSpan.FromMinutes(1));
        using var expired = await client.GetAsync($"/{link.Code}");
        await AssertProblemAsync(expired, HttpStatusCode.Gone);
    }

    [Fact]
    public async Task DeleteInvalidatesWarmCache()
    {
        using var client = factory.Client();
        var link = await CreateAsync(client);
        using var warm = await client.GetAsync($"/{link.Code}");
        Assert.Equal(HttpStatusCode.Found, warm.StatusCode);
        using var deleted = await client.DeleteAsync($"/api/v1/links/{link.Code}");
        Assert.Equal(HttpStatusCode.NoContent, deleted.StatusCode);
        using var redirect = await client.GetAsync($"/{link.Code}");
        await AssertProblemAsync(redirect, HttpStatusCode.Gone);
        Assert.False((await client.GetFromJsonAsync<LinkDetails>($"/api/v1/links/{link.Code}"))!.IsActive);
    }

    [Fact]
    public async Task StatsShowThreeBackgroundClicks()
    {
        using var client = factory.Client();
        var link = await CreateAsync(client);
        client.DefaultRequestHeaders.Referrer = new Uri("https://referrer.example/campaign");
        for (var i = 0; i < 3; i++)
        {
            using var response = await client.GetAsync($"/{link.Code}");
            Assert.Equal(HttpStatusCode.Found, response.StatusCode);
        }
        var stopwatch = Stopwatch.StartNew();
        LinkStats? stats;
        do
        {
            stats = await client.GetFromJsonAsync<LinkStats>($"/api/v1/links/{link.Code}/stats");
            if (stats!.TotalClicks == 3) break;
            await Task.Delay(25);
        } while (stopwatch.Elapsed < TimeSpan.FromSeconds(10));
        Assert.Equal(3, stats!.TotalClicks);
